+        final double finalW = w;
+        for (Model m : models) {
+            for (Node n : nodes) {
+                weights.computeIfAbsent(Tuple.tuple(m, n), key -> random.nextDouble(minWeight(m, n, finalW), maxWeight(m, n, finalW)));
+            }
+        }
