+        }
+
+        for (Model m : models) {
+            for (Node n : nodes) {
+                Tuple<Model, Node> assignment = Tuple.tuple(m, n);
+                allocationValues.put(assignment, allocationVars.get(assignment).getValue().doubleValue());
