+            ByteSizeValue.ofGb(2).getBytes(),
+            ByteSizeValue.ofGb(3).getBytes(),
+            ByteSizeValue.ofGb(4).getBytes() };
+
+        List<Node> nodes = new ArrayList<>();
+        for (int i = 0; i < 1 + 3 * scale; i++) {
+            int cores = randomIntBetween(2, 32);
