+                    RestStatus.INTERNAL_SERVER_ERROR,
+                    pyTorchResult.getInferenceResult().length
+                );
+            }
+            double[][] starts = pyTorchResult.getInferenceResult()[0];
+            double[][] ends = pyTorchResult.getInferenceResult()[1];
